{"op":"add","path":"/root","value":"composer"}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Turn a rough brief into deck directions","lede":"Say what the talk is about and who it's for, and get several visual directions to choose from.","runLabel":"Sketch my directions","columns":"2"},"children":["group-talk","group-audience","run-note"],"on":{"press":[{"action":"validateForm"},{"action":"run"}]}}}
{"op":"add","path":"/elements/group-talk","value":{"type":"FieldGroup","props":{"title":"What's the talk?"},"children":["topic-field","brand-field","references-field"]}}
{"op":"add","path":"/elements/topic-field","value":{"type":"Textarea","props":{"label":"Topic","name":"topic","placeholder":"e.g. Our Series A story: why now, why us","rows":5,"value":{"$bindState":"/inputs/brief/topic"},"checks":[{"type":"required","message":"Tell us what the talk is about."}]},"children":[]}}
{"op":"add","path":"/elements/brand-field","value":{"type":"Textarea","props":{"label":"Brand guidelines","name":"brand_guidelines","placeholder":"Colours, fonts, logo rules…","rows":3,"value":{"$bindState":"/inputs/brief/brand_guidelines"}},"children":[]}}
{"op":"add","path":"/elements/references-field","value":{"type":"Textarea","props":{"label":"References","name":"existing_references","placeholder":"Past decks or templates to echo, or to steer clear of.","rows":3,"value":{"$bindState":"/inputs/brief/existing_references"}},"children":[]}}
{"op":"add","path":"/elements/group-audience","value":{"type":"FieldGroup","props":{"title":"Who's it for?"},"children":["goal-field","audience-field","tone-field"]}}
{"op":"add","path":"/elements/goal-field","value":{"type":"Segmented","props":{"label":"Goal","name":"goal","options":["pitch investors","sell to clients","internal training","keynote"],"value":{"$bindState":"/inputs/brief/goal"}},"children":[]}}
{"op":"add","path":"/elements/audience-field","value":{"type":"Segmented","props":{"label":"Audience","name":"audience","options":["executives","technical team","general public"],"value":{"$bindState":"/inputs/brief/audience"}},"children":[]}}
{"op":"add","path":"/elements/tone-field","value":{"type":"Segmented","props":{"label":"Tone","name":"tone","options":["formal","playful","innovative","trustworthy","artsy"],"value":{"$bindState":"/inputs/brief/tone"}},"children":[]}}
{"op":"add","path":"/elements/run-note","value":{"type":"Text","props":{"text":"Only the topic is needed. Everything else sharpens the directions.","variant":"muted"},"children":[]}}
